                                hh_tens <= 4'd1;
                                hh_ones <= 4'd2;
                                pm_reg <= ~pm_reg;
                            end else if (hh_tens == 4'd1 && hh_ones == 4'd2) begin
                                hh_tens <= 4'd0;
                                hh_ones <= 4'd1;
                            end else if (hh_tens == 4'd0 && hh_ones == 4'd9) begin
                                hh_tens <= 4'd1;
                                hh_ones <= 4'd0;
                            end else begin
                                hh_ones <= hh_ones + 4'd1;
                            end
                        end else begin
                            mm_tens <= mm_tens + 4'd1;
                        end
                    end else begin
                        mm_ones <= mm_ones + 4'd1;
                    end
                end else begin
                    ss_tens <= ss_tens + 4'd1;
                end
            end else begin
                ss_ones <= ss_ones + 4'd1;
            end
        end
    end
endmodule

